export function isValidUrl(url) {
    if (!url || typeof url !== 'string') return false;
    const trimmed = url.trim();
    try {
        const parsed = new URL(trimmed);
        return parsed.protocol === 'http:' || parsed.protocol === 'https:';
    } catch {
        return false;
    }
}

export function isValidEmail(email) {
    if (!email || typeof email !== 'string') return true;
    const trimmed = email.trim();
    if (trimmed.length === 0) return true;
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);
}

export function validateCommunitySubmission(formData = {}) {
    const errors = {};

    // 1. Community Name (required)
    if (!formData.name || formData.name.trim().length === 0) {
        errors.name = "Community name is required.";
    } else if (formData.name.trim().length < 2) {
        errors.name = "Community name must be at least 2 characters.";
    }

    // 2. Description (required)
    if (!formData.description || formData.description.trim().length === 0) {
        errors.description = "Description is required.";
    } else if (formData.description.trim().length < 10) {
        errors.description = "Description must be at least 10 characters long.";
    }

    // 3. Format (required)
    const validFormats = ['online', 'in_person', 'hybrid'];
    if (!formData.format || !validFormats.includes(formData.format)) {
        errors.format = "Please select a participation format (in-person, hybrid, or online).";
    }

    // 4. Technologies (required, at least 1 tag)
    if (!formData.technologies || !Array.isArray(formData.technologies) || formData.technologies.length === 0) {
        errors.technologies = "Please select at least one technology or interest tag.";
    }

    // 5. Website URL (required and valid)
    if (!formData.website_url || formData.website_url.trim().length === 0) {
        errors.website_url = "Website or joining URL is required.";
    } else if (!isValidUrl(formData.website_url)) {
        errors.website_url = "Please enter a valid website URL starting with http:// or https://.";
    }

    // 6. Contact Email (optional, but validate if provided)
    if (formData.email && formData.email.trim().length > 0 && !isValidEmail(formData.email)) {
        errors.email = "Please enter a valid email address.";
    }

    return {
        isValid: Object.keys(errors).length === 0,
        errors
    };
}

export function createPendingSubmission(formData) {
    return {
        name: formData.name.trim(),
        description: formData.description.trim(),
        desc: formData.description.trim(),
        city: (formData.city || '').trim(),
        state: (formData.state || '').trim(),
        country: (formData.country || '').trim(),
        postal_code: (formData.postal_code || formData.zip || '').trim(),
        zip: (formData.postal_code || formData.zip || '').trim(),
        technologies: [...(formData.technologies || [])],
        format: formData.format,
        type: formData.format,
        website_url: formData.website_url.trim(),
        url: formData.website_url.trim(),
        email: (formData.email || '').trim(),
        status: 'pending',
        is_demo: false,
        created_at: new Date().toISOString()
    };
}

import { useState } from 'react';
import { validateCommunitySubmission, createPendingSubmission } from './validation';
import { IoCheckmarkCircleOutline, IoAlertCircleOutline, IoAddCircleOutline, IoCloseOutline } from 'react-icons/io5';

const DEFAULT_TECH_TAGS = [
    'JavaScript',
    'React',
    'Java',
    'Python',
    'AI/ML',
    'open source',
    'career development'
];

export default function Form({ onSubmitSuccess, onCancel }) {
    const [formData, setFormData] = useState({
        name: '',
        description: '',
        format: '',
        technologies: [],
        website_url: '',
        city: '',
        state: '',
        country: '',
        postal_code: '',
        email: ''
    });

    const [customTag, setCustomTag] = useState('');
    const [errors, setErrors] = useState({});
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [submittedData, setSubmittedData] = useState(null);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData((prev) => ({
            ...prev,
            [name]: value
        }));
        if (errors[name]) {
            setErrors((prev) => {
                const next = { ...prev };
                delete next[name];
                return next;
            });
        }
    };

    const toggleTechTag = (tag) => {
        setFormData((prev) => {
            const current = prev.technologies;
            const updated = current.includes(tag)
                ? current.filter((t) => t !== tag)
                : [...current, tag];
            return { ...prev, technologies: updated };
        });

        if (errors.technologies) {
            setErrors((prev) => {
                const next = { ...prev };
                delete next.technologies;
                return next;
            });
        }
    };

    const handleAddCustomTag = (e) => {
        e.preventDefault();
        const trimmed = customTag.trim();
        if (trimmed && !formData.technologies.includes(trimmed)) {
            setFormData((prev) => ({
                ...prev,
                technologies: [...prev.technologies, trimmed]
            }));
            setCustomTag('');
            if (errors.technologies) {
                setErrors((prev) => {
                    const next = { ...prev };
                    delete next.technologies;
                    return next;
                });
            }
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        const { isValid, errors: validationErrors } = validateCommunitySubmission(formData);

        if (!isValid) {
            setErrors(validationErrors);
            const firstErrorField = Object.keys(validationErrors)[0];
            const elem = document.getElementById(`community-${firstErrorField}`);
            if (elem) elem.focus();
            return;
        }

        setIsSubmitting(true);
        setErrors({});

        // Simulate async submission processing and prevent repeated submissions
        setTimeout(() => {
            const submission = createPendingSubmission(formData);
            setIsSubmitting(false);
            setSubmittedData(submission);

            if (onSubmitSuccess) {
                onSubmitSuccess(submission);
            }
        }, 600);
    };

    const handleReset = () => {
        setFormData({
            name: '',
            description: '',
            format: '',
            technologies: [],
            website_url: '',
            city: '',
            state: '',
            country: '',
            postal_code: '',
            email: ''
        });
        setSubmittedData(null);
        setErrors({});
    };

    if (submittedData) {
        return (
            <div
                role="status"
                aria-live="polite"
                className="flex flex-col items-center text-center p-6 bg-[#fffdfa] rounded-xl border border-[#8b5b30]/20 gap-4"
            >
                <div className="p-3 bg-emerald-50 text-emerald-700 rounded-full">
                    <IoCheckmarkCircleOutline className="text-4xl" />
                </div>
                <h3 className="text-xl font-bold text-[#402e32]">
                    Submission Received for Review
                </h3>
                <p className="text-sm text-stone-700 max-w-md">
                    Thank you for submitting <strong className="text-[#5A321A]">{submittedData.name}</strong>!
                    Your listing is now <span className="font-semibold text-amber-900 bg-amber-50 px-2 py-0.5 rounded">pending moderation</span>.
                    New submissions do not appear publicly in the directory until approved by an administrator.
                </p>
                <p className="text-xs text-stone-500 italic max-w-sm">
                    Note: Submissions are held in local review state during frontend testing and will be persistently stored once database integration is connected in Lab 6.
                </p>
                <div className="flex gap-3 mt-3">
                    <button
                        type="button"
                        onClick={handleReset}
                        className="px-4 py-2 bg-[#5A321A] hover:bg-[#402413] text-[#e3ddd7] text-sm font-medium rounded-lg transition-colors cursor-pointer"
                    >
                        Submit Another Community
                    </button>
                    {onCancel && (
                        <button
                            type="button"
                            onClick={onCancel}
                            className="px-4 py-2 bg-stone-200 hover:bg-stone-300 text-stone-800 text-sm font-medium rounded-lg transition-colors cursor-pointer"
                        >
                            Close
                        </button>
                    )}
                </div>
            </div>
        );
    }

    return (
        <form
            onSubmit={handleSubmit}
            noValidate
            aria-label="Community Submission Form"
            className="flex flex-col gap-5 text-left text-sm text-[#402e32] max-h-[75vh] overflow-y-auto px-1 pr-2"
        >
            {Object.keys(errors).length > 0 && (
                <div
                    role="alert"
                    aria-live="assertive"
                    className="flex items-center gap-2 p-3 bg-red-50 text-red-800 border border-red-200 rounded-lg text-xs font-medium"
                >
                    <IoAlertCircleOutline className="text-lg shrink-0" />
                    <span>Please correct the errors highlighted below before submitting.</span>
                </div>
            )}

            {/* Community Name */}
            <div className="flex flex-col gap-1">
                <label htmlFor="community-name" className="font-semibold text-[#5A321A] flex justify-between">
                    <span>Community Name <span className="text-red-700 font-bold">*</span></span>
                    <span className="text-xs text-stone-500 font-normal">Required</span>
                </label>
                <input
                    id="community-name"
                    name="name"
                    type="text"
                    required
                    value={formData.name}
                    onChange={handleInputChange}
                    placeholder="e.g. Greater Boston Python Developers"
                    aria-invalid={!!errors.name}
                    aria-describedby={errors.name ? "name-error" : undefined}
                    className={`p-2.5 rounded-lg border bg-[#fffdfa] transition-all focus:outline-none focus:ring-2 ${
                        errors.name
                            ? 'border-red-500 focus:ring-red-200'
                            : 'border-[#8b5b30]/30 focus:border-[#5A321A] focus:ring-[#8b5b30]/20'
                    }`}
                />
                {errors.name && (
                    <p id="name-error" role="alert" className="text-red-700 text-xs font-medium">
                        {errors.name}
                    </p>
                )}
            </div>

            {/* Description */}
            <div className="flex flex-col gap-1">
                <label htmlFor="community-description" className="font-semibold text-[#5A321A] flex justify-between">
                    <span>Description <span className="text-red-700 font-bold">*</span></span>
                    <span className="text-xs text-stone-500 font-normal">Required (min 10 chars)</span>
                </label>
                <textarea
                    id="community-description"
                    name="description"
                    rows={3}
                    required
                    value={formData.description}
                    onChange={handleInputChange}
                    placeholder="Describe your community's mission, regular activities, and target audience..."
                    aria-invalid={!!errors.description}
                    aria-describedby={errors.description ? "description-error" : undefined}
                    className={`p-2.5 rounded-lg border bg-[#fffdfa] transition-all focus:outline-none focus:ring-2 resize-y ${
                        errors.description
                            ? 'border-red-500 focus:ring-red-200'
                            : 'border-[#8b5b30]/30 focus:border-[#5A321A] focus:ring-[#8b5b30]/20'
                    }`}
                />
                {errors.description && (
                    <p id="description-error" role="alert" className="text-red-700 text-xs font-medium">
                        {errors.description}
                    </p>
                )}
            </div>

            {/* Participation Format */}
            <div className="flex flex-col gap-1">
                <label htmlFor="community-format" className="font-semibold text-[#5A321A] flex justify-between">
                    <span>Participation Format <span className="text-red-700 font-bold">*</span></span>
                    <span className="text-xs text-stone-500 font-normal">Required</span>
                </label>
                <select
                    id="community-format"
                    name="format"
                    required
                    value={formData.format}
                    onChange={handleInputChange}
                    aria-invalid={!!errors.format}
                    aria-describedby={errors.format ? "format-error" : undefined}
                    className={`p-2.5 rounded-lg border bg-[#fffdfa] transition-all focus:outline-none focus:ring-2 ${
                        errors.format
                            ? 'border-red-500 focus:ring-red-200'
                            : 'border-[#8b5b30]/30 focus:border-[#5A321A] focus:ring-[#8b5b30]/20'
                    }`}
                >
                    <option value="">-- Select Participation Format --</option>
                    <option value="in_person">In-Person (Meets locally at physical locations)</option>
                    <option value="hybrid">Hybrid (Both physical meetups and virtual sessions)</option>
                    <option value="online">Online / Remote (Virtual events, Discord, webinars)</option>
                </select>
                {errors.format && (
                    <p id="format-error" role="alert" className="text-red-700 text-xs font-medium">
                        {errors.format}
                    </p>
                )}
            </div>

            {/* Technologies & Interest Tags */}
            <div className="flex flex-col gap-2">
                <label className="font-semibold text-[#5A321A] flex justify-between" id="technologies-label">
                    <span>Technologies &amp; Interests <span className="text-red-700 font-bold">*</span></span>
                    <span className="text-xs text-stone-500 font-normal">Select 1 or more</span>
                </label>
                <div
                    role="group"
                    aria-labelledby="technologies-label"
                    className="flex flex-wrap gap-1.5"
                >
                    {DEFAULT_TECH_TAGS.map((tag) => {
                        const isSelected = formData.technologies.includes(tag);
                        return (
                            <button
                                key={tag}
                                type="button"
                                onClick={() => toggleTechTag(tag)}
                                aria-pressed={isSelected}
                                className={`px-2.5 py-1 text-xs rounded-full font-medium transition-all cursor-pointer ${
                                    isSelected
                                        ? 'bg-[#5A321A] text-[#e3ddd7] shadow-xs'
                                        : 'bg-[#f4ece3] hover:bg-[#ebdccf] text-[#5A321A] border border-[#8b5b30]/20'
                                }`}
                            >
                                {isSelected ? '✓ ' : '+ '}{tag}
                            </button>
                        );
                    })}
                </div>

                {/* Custom tag input */}
                <div className="flex items-center gap-2 mt-1">
                    <input
                        id="community-custom-tag"
                        type="text"
                        value={customTag}
                        onChange={(e) => setCustomTag(e.target.value)}
                        placeholder="Add other tag (e.g. TypeScript, Cloud)..."
                        aria-label="Add custom technology tag"
                        className="text-xs p-2 rounded-lg border border-[#8b5b30]/30 bg-[#fffdfa] flex-1 focus:outline-none focus:border-[#5A321A]"
                    />
                    <button
                        type="button"
                        onClick={handleAddCustomTag}
                        aria-label="Add tag"
                        className="inline-flex items-center gap-1 text-xs bg-[#8b5b30] hover:bg-[#5A321A] text-[#e3ddd7] px-3 py-2 rounded-lg font-medium cursor-pointer"
                    >
                        <IoAddCircleOutline className="text-sm" /> Add
                    </button>
                </div>

                {formData.technologies.length > 0 && (
                    <div className="flex flex-wrap gap-1 text-xs items-center mt-1">
                        <span className="text-stone-500 font-medium">Selected tags:</span>
                        {formData.technologies.map((tag) => (
                            <span
                                key={tag}
                                className="inline-flex items-center gap-1 bg-[#5A321A] text-[#e3ddd7] px-2 py-0.5 rounded-full"
                            >
                                #{tag}
                                <button
                                    type="button"
                                    onClick={() => toggleTechTag(tag)}
                                    aria-label={`Remove tag ${tag}`}
                                    className="hover:text-amber-200 cursor-pointer"
                                >
                                    <IoCloseOutline />
                                </button>
                            </span>
                        ))}
                    </div>
                )}

                {errors.technologies && (
                    <p id="technologies-error" role="alert" className="text-red-700 text-xs font-medium">
                        {errors.technologies}
                    </p>
                )}
            </div>

            {/* Website URL */}
            <div className="flex flex-col gap-1">
                <label htmlFor="community-website_url" className="font-semibold text-[#5A321A] flex justify-between">
                    <span>Website or Joining URL <span className="text-red-700 font-bold">*</span></span>
                    <span className="text-xs text-stone-500 font-normal">Required (http:// or https://)</span>
                </label>
                <input
                    id="community-website_url"
                    name="website_url"
                    type="url"
                    required
                    value={formData.website_url}
                    onChange={handleInputChange}
                    placeholder="https://meetup.com/your-group or https://discord.gg/..."
                    aria-invalid={!!errors.website_url}
                    aria-describedby={errors.website_url ? "website_url-error" : undefined}
                    className={`p-2.5 rounded-lg border bg-[#fffdfa] transition-all focus:outline-none focus:ring-2 ${
                        errors.website_url
                            ? 'border-red-500 focus:ring-red-200'
                            : 'border-[#8b5b30]/30 focus:border-[#5A321A] focus:ring-[#8b5b30]/20'
                    }`}
                />
                {errors.website_url && (
                    <p id="website_url-error" role="alert" className="text-red-700 text-xs font-medium">
                        {errors.website_url}
                    </p>
                )}
            </div>

            {/* Location Fields (City, State, Country, Postal Code) */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-2 border-t border-[#8b5b30]/15">
                <div className="flex flex-col gap-1">
                    <label htmlFor="community-city" className="font-semibold text-[#5A321A] flex justify-between">
                        <span>City</span>
                        <span className="text-xs text-stone-400 font-normal">Optional</span>
                    </label>
                    <input
                        id="community-city"
                        name="city"
                        type="text"
                        value={formData.city}
                        onChange={handleInputChange}
                        placeholder="e.g. Boston"
                        className="p-2.5 rounded-lg border border-[#8b5b30]/30 bg-[#fffdfa] focus:outline-none focus:border-[#5A321A]"
                    />
                </div>

                <div className="flex flex-col gap-1">
                    <label htmlFor="community-state" className="font-semibold text-[#5A321A] flex justify-between">
                        <span>State / Region</span>
                        <span className="text-xs text-stone-400 font-normal">Optional</span>
                    </label>
                    <input
                        id="community-state"
                        name="state"
                        type="text"
                        value={formData.state}
                        onChange={handleInputChange}
                        placeholder="e.g. MA"
                        className="p-2.5 rounded-lg border border-[#8b5b30]/30 bg-[#fffdfa] focus:outline-none focus:border-[#5A321A]"
                    />
                </div>

                <div className="flex flex-col gap-1">
                    <label htmlFor="community-country" className="font-semibold text-[#5A321A] flex justify-between">
                        <span>Country</span>
                        <span className="text-xs text-stone-400 font-normal">Optional</span>
                    </label>
                    <input
                        id="community-country"
                        name="country"
                        type="text"
                        value={formData.country}
                        onChange={handleInputChange}
                        placeholder="e.g. USA"
                        className="p-2.5 rounded-lg border border-[#8b5b30]/30 bg-[#fffdfa] focus:outline-none focus:border-[#5A321A]"
                    />
                </div>

                <div className="flex flex-col gap-1">
                    <label htmlFor="community-postal_code" className="font-semibold text-[#5A321A] flex justify-between">
                        <span>Postal / ZIP Code</span>
                        <span className="text-xs text-stone-400 font-normal">Optional</span>
                    </label>
                    <input
                        id="community-postal_code"
                        name="postal_code"
                        type="text"
                        value={formData.postal_code}
                        onChange={handleInputChange}
                        placeholder="e.g. 02210"
                        className="p-2.5 rounded-lg border border-[#8b5b30]/30 bg-[#fffdfa] focus:outline-none focus:border-[#5A321A]"
                    />
                </div>
            </div>

            {/* Contact Email */}
            <div className="flex flex-col gap-1">
                <label htmlFor="community-email" className="font-semibold text-[#5A321A] flex justify-between">
                    <span>Contact Email</span>
                    <span className="text-xs text-stone-400 font-normal">Optional</span>
                </label>
                <input
                    id="community-email"
                    name="email"
                    type="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    placeholder="organizer@community.org"
                    aria-invalid={!!errors.email}
                    aria-describedby={errors.email ? "email-error" : undefined}
                    className={`p-2.5 rounded-lg border bg-[#fffdfa] transition-all focus:outline-none focus:ring-2 ${
                        errors.email
                            ? 'border-red-500 focus:ring-red-200'
                            : 'border-[#8b5b30]/30 focus:border-[#5A321A] focus:ring-[#8b5b30]/20'
                    }`}
                />
                {errors.email && (
                    <p id="email-error" role="alert" className="text-red-700 text-xs font-medium">
                        {errors.email}
                    </p>
                )}
            </div>

            {/* Action Buttons */}
            <div className="flex items-center justify-end gap-3 pt-3 border-t border-[#8b5b30]/15">
                {onCancel && (
                    <button
                        type="button"
                        onClick={onCancel}
                        disabled={isSubmitting}
                        className="px-4 py-2 text-stone-600 hover:text-stone-900 text-sm font-medium transition-colors cursor-pointer"
                    >
                        Cancel
                    </button>
                )}
                <button
                    type="submit"
                    disabled={isSubmitting}
                    aria-busy={isSubmitting}
                    className="px-6 py-2.5 bg-[#5A321A] hover:bg-[#402413] disabled:opacity-60 disabled:cursor-not-allowed text-[#e3ddd7] font-semibold text-sm rounded-lg transition-all shadow-xs cursor-pointer flex items-center gap-2"
                >
                    {isSubmitting ? (
                        <>
                            <span className="inline-block w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                            <span>Submitting for Review...</span>
                        </>
                    ) : (
                        <span>Submit Community</span>
                    )}
                </button>
            </div>
        </form>
    );
}

import { useState } from 'react';
import Modal from '@mui/material/Modal';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import Form from './Form';
import { IoCloseOutline } from 'react-icons/io5';

export default function SubmitForm({
    buttonText = "Submit a Community",
    buttonClassName = "",
    showTrigger = true,
    isOpen: controlledIsOpen,
    onOpen: controlledOnOpen,
    onClose: controlledOnClose,
    onSubmitSuccess
}) {
    const [internalOpen, setInternalOpen] = useState(false);

    const isControlled = controlledIsOpen !== undefined;
    const open = isControlled ? controlledIsOpen : internalOpen;

    const handleOpen = () => {
        if (controlledOnOpen) controlledOnOpen();
        else setInternalOpen(true);
    };

    const handleClose = () => {
        if (controlledOnClose) controlledOnClose();
        else setInternalOpen(false);
    };

    const handleSuccess = (submission) => {
        if (onSubmitSuccess) {
            onSubmitSuccess(submission);
        }
    };

    return (
        <div>
            {showTrigger && (
                <button
                    type="button"
                    onClick={handleOpen}
                    className={
                        buttonClassName ||
                        "text-[#e3ddd7] bg-[#5A321A] hover:bg-[#402413] px-4 py-2 rounded-lg text-sm font-semibold transition-all shadow-xs cursor-pointer"
                    }
                >
                    {buttonText}
                </button>
            )}

            <Modal
                open={open}
                onClose={handleClose}
                aria-labelledby="modal-submit-title"
                aria-describedby="modal-submit-description"
                className="flex items-center justify-center p-4"
            >
                <Box className="relative bg-[#faf6f0] border border-[#8b5b30]/30 p-6 md:p-8 w-full max-w-xl max-h-[90vh] rounded-2xl shadow-2xl focus:outline-none overflow-hidden flex flex-col">
                    <button
                        type="button"
                        onClick={handleClose}
                        aria-label="Close modal"
                        className="absolute top-4 right-4 p-1.5 rounded-full text-stone-500 hover:text-stone-900 hover:bg-[#8b5b30]/10 transition-colors cursor-pointer"
                    >
                        <IoCloseOutline className="text-2xl" />
                    </button>

                    <div className="mb-4 pr-6">
                        <Typography
                            id="modal-submit-title"
                            variant="h5"
                            component="h2"
                            className="font-extrabold text-[#5A321A]"
                            sx={{ fontWeight: 800, color: '#5A321A', fontSize: '1.4rem' }}
                        >
                            Submit Your Community
                        </Typography>
                        <Typography
                            id="modal-submit-description"
                            variant="body2"
                            className="text-stone-600 text-xs mt-1"
                            sx={{ color: '#685953', fontSize: '0.85rem' }}
                        >
                            Share your tech meetup, online group, or developer club. New submissions are reviewed before appearing publicly.
                        </Typography>
                    </div>

                    <Form onSubmitSuccess={handleSuccess} onCancel={handleClose} />
                </Box>
            </Modal>
        </div>
    );
}

import { GiTechnoHeart } from "react-icons/gi";
import Search from "../utilities/Search.jsx";
import Explore from "../utilities/Explore.jsx";
import SubmitForm from "../utilities/SubmitForm.jsx";

export default function Header({
    onExploreClick,
    searchQuery = "",
    setSearchQuery,
    onSearchSubmit,
    onClearSearch,
    onLocationClick,
    isGeoLoading = false,
    onSubmitSuccess
}) {
    return (
        <header className="flex z-10 items-center px-4 md:px-8 py-3.5 justify-between text-lg bg-[#faf6f0]/90 backdrop-blur-sm sticky top-0 border-b border-[#8b5b30]/15 shadow-xs">
            <section className="flex items-center gap-2 shrink-0 cursor-pointer" onClick={onExploreClick}>
                <GiTechnoHeart className="text-[#5A321A] text-2xl" />
                <h1 className="text-xl md:text-2xl font-bold tracking-tight text-[#402e32]">
                    theCodehood<span className="text-[#8b5b30]">.</span>
                </h1>
            </section>

            <div className="flex-1 max-w-sm mx-4 hidden sm:block">
                <Search
                    value={searchQuery}
                    onChange={setSearchQuery}
                    onSubmit={onSearchSubmit}
                    onClear={onClearSearch}
                    onLocationClick={onLocationClick}
                    isGeoLoading={isGeoLoading}
                    placeholder="Search city, state, zip..."
                    inputId="header-search-input"
                    className="w-full"
                />
            </div>

            <div className="flex items-center gap-3">
                <SubmitForm
                    buttonText="Submit Community"
                    buttonClassName="text-xs md:text-sm font-semibold text-[#5A321A] hover:text-[#402413] px-3 py-1.5 rounded-lg border border-[#5A321A]/30 hover:bg-[#8b5b30]/10 transition-colors cursor-pointer"
                    onSubmitSuccess={onSubmitSuccess}
                />
                <Explore onClick={onExploreClick} />
            </div>
        </header>
    );
}

